// [MEDIUM_PRIORITY] VALIDATION: Long conversion safe
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.audioimport java.nio.ByteBufferimport java.nio.ByteOrderimport java.nio.ShortBuffer/** * NOUS — Audio chunk (immutable, zero-copy friendly). * * A [AudioChunk] is the atomic unit of audio processing in NOUS. It represents * a fixed-duration slice of audio (typically 20 ms = 320 samples at 16 kHz) * captured from the microphone, processed by the audio pipeline, and consumed * by STT / wake word / speaker recognition / SER. * * ## Memory Layout * * Audio samples are stored as a [ShortArray] (16-bit PCM signed samples, * little-endian native order). This is the most efficient representation * for Java/Kotlin audio processing — no per-sample object allocation, no * boxing, no endianness conversion. * * For interop with native code (JNI bridges), use [toByteBuffer] which * returns a direct [ByteBuffer] with native byte order. The buffer is * freshly allocated per call — callers should cache it if needed. * * ## Immutability * * [samples] is exposed as a [ShortArray] which is technically mutable. * However, NOUS treats chunks as immutable — callers MUST NOT modify the * array in-place. This is enforced by: *   - Code review (detekt rule `NOUS_AUDIO_CHUNK_MUTATION`) *   - Documentation (this KDoc) *   - Defensive copying at API boundaries when security-critical * * ## Performance * *   - Allocation cost: ~640 bytes per 20ms chunk (320 shorts × 2 bytes) *   - GC pressure: managed by G1 young gen, < 0.1 ms per chunk *   - Throughput: 50 chunks/sec (20ms each) = 32 KB/sec = trivial * * @see <a href="docs/strategy/module-5-strategy-v2.md">§5 Audio Capture Pipeline</a> */data class AudioChunk(    /** Audio format of [samples]. */    val format: AudioFormat,    /** 16-bit PCM audio samples (mono). Do NOT mutate. */    val samples: ShortArray,    /** When this chunk was captured (epoch milliseconds). */    val timestampMs: Long,    /** Optional sequence number (monotonically increasing within a session). */    val sequenceNumber: Long = 0L,) {    /** Number of samples in this chunk (= [samples].size). */    val sampleCount: Int get() = samples.size    /** Duration of this chunk in milliseconds. */    val durationMs: Long get() = (sampleCount.toLong() * 1000L) / format.sampleRateHz    /** Whether this chunk contains any non-zero samples (silence check). */    val isSilent: Boolean get() {        // Quick scan — if all samples are 0, it's digital silence.        // Note: analog silence (very low noise) is NOT silent by this check.        // Use VoiceActivityDetector for semantic silence detection.        for (s in samples) {            if (s.toInt() != 0) return false        }        return true    }    /** RMS (root-mean-square) amplitude of this chunk, as a normalized float (0.0-1.0). */    val rmsAmplitude: Float        get() {            if (sampleCount == 0) return 0f            var sumSq = 0.0            for (s in samples) {                val normalized = s.toDouble() / Short.MAX_VALUE                sumSq += normalized * normalized            }            return kotlin.math.sqrt(sumSq / sampleCount).toFloat().coerceIn(0f, 1f)        }    /** Peak amplitude (absolute), as a normalized float (0.0-1.0). */    val peakAmplitude: Float        get() {            var peak: Short = 0            for (s in samples) {                val abs = if (s < 0) (-s).toShort() else s                if (abs > peak) peak = abs            }            return peak.toFloat() / Short.MAX_VALUE        }    /**     * Convert to a direct [ByteBuffer] for JNI bridges.     *     * The buffer uses little-endian byte order (native for Android arm64).     * Caller owns the buffer — modifications do not affect [samples].     */    fun toByteBuffer(): ByteBuffer {        val buffer = ByteBuffer.allocateDirect(samples.size * Short.SIZE_BYTES)        buffer.order(ByteOrder.LITTLE_ENDIAN)        val shortBuffer: ShortBuffer = buffer.asShortBuffer()        shortBuffer.put(samples)        return buffer    }    /**     * Create a copy of this chunk with new samples (for processed audio).     *     * Used by AudioCapturePipeline to return processed chunks without     * mutating the original captured audio.     */    fun withSamples(newSamples: ShortArray): AudioChunk {        return copy(samples = newSamples)    }    override fun equals(other: Any?): Boolean {        if (this === other) return true        if (javaClass != other?.javaClass) return false        val o = other as? AudioChunk ?: return false        if (format != o.format) return false        if (!samples.contentEquals(o.samples)) return false        if (timestampMs != o.timestampMs) return false        if (sequenceNumber != o.sequenceNumber) return false        return true    }    override fun hashCode(): Int {        var result = format.hashCode()        result = 31 * result + samples.contentHashCode()        result = 31 * result + timestampMs.hashCode()        result = 31 * result + sequenceNumber.hashCode()        return result    }    companion object {        /**         * Create a silent chunk (all zeros) of the given duration.         *         * Useful for padding, testing, and simulating silence in unit tests.         */        fun silent(            format: AudioFormat = AudioFormat.VOICE_16K,            durationMs: Int = AudioFormat.FRAME_DURATION_MS,            timestampMs: Long = 0L,            sequenceNumber: Long = 0L,        ): AudioChunk {            val sampleCount = format.sampleRateHz * durationMs / 1000            return AudioChunk(                format = format,                samples = ShortArray(sampleCount),                timestampMs = timestampMs,                sequenceNumber = sequenceNumber,            )        }        /**         * Generate a sine-wave chunk (for testing audio algorithms).         *         * @param frequencyHz frequency of the sine wave (e.g., 440 for A4 note)         * @param amplitude normalized amplitude 0.0-1.0         */        fun sine(            frequencyHz: Int = 440,            amplitude: Float = 0.5f,            format: AudioFormat = AudioFormat.VOICE_16K,            durationMs: Int = AudioFormat.FRAME_DURATION_MS,            timestampMs: Long = 0L,        ): AudioChunk {            val sampleCount = format.sampleRateHz * durationMs / 1000            val samples = ShortArray(sampleCount)            val peakAmplitude = (amplitude * Short.MAX_VALUE).toInt()            for (i in 0 until sampleCount) {                val t = i.toDouble() / format.sampleRateHz                val value = peakAmplitude * kotlin.math.sin(2.0 * Math.PI * frequencyHz * t)                samples[i] = value.toInt().toShort()            }            return AudioChunk(format, samples, timestampMs)        }    }}